const arcaneOrbSheet=new Image();arcaneOrbSheet.assetSrc='assets/arcane-orb-v1.png';
function beginArcaneOrb(e){let side=e.orbSide===1?-1:1;e.orbSide=side;e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'orbShiftingSanctuary',bespoke:true,windup:1.4,origin:{x:e.x,y:e.y},angle:Math.atan2(p.y-e.y,p.x-e.x),side,first:false,second:false};}
function arcaneOrbUnsafe(a,point,phase){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,r=Math.hypot(dx,dy);if(r>300)return false;if(r<1e-8)return true;let gap=a.angle+phase*a.side*Math.PI*2/3,diff=Math.atan2(Math.sin(Math.atan2(dy,dx)-gap),Math.cos(Math.atan2(dy,dx)-gap));return Math.abs(diff)>Math.PI*35/180+1e-8;}
const arcaneOrbAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r9e6')return arcaneOrbAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='orbShiftingSanctuary'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=260&&clear){beginArcaneOrb(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,62*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.first&&e.elapsed>=1.4){a.first=true;e.struck=true;if(arcaneOrbUnsafe(a,p,0)&&lineClear(a.origin,p))hurt(60);playSound('impact',e.x,e.y);}
 if(!dead&&!a.second&&e.elapsed>=3){a.second=true;e.struck=true;if(arcaneOrbUnsafe(a,p,1)&&lineClear(a.origin,p))hurt(84);playSound('impact',e.x,e.y);}
 if(e.elapsed>=4){e.attack=null;e.state='idle';e.t=3.2;}
};
const arcaneOrbDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r9e6'||!arcaneOrbSheet.complete||!arcaneOrbSheet.naturalWidth||!arcaneOrbSheet.naturalHeight)return arcaneOrbDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='orbShiftingSanctuary')f={row:2,col:e.elapsed<.7?0:e.elapsed<1.4?1:e.elapsed<1.65?2:e.elapsed<2.3?0:e.elapsed<3?1:e.elapsed<3.25?2:3};let q=project(e.x,e.y),sw=arcaneOrbSheet.naturalWidth/4,sh=arcaneOrbSheet.naturalHeight/3,w=210,h=w*sh/sw,anchor=[[.87,.87,.85,.87],[.77,.75,.81,.79],[.74,.82,.83,.79]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y-16-Math.sin((e.anim||0)*2.5)*3);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,arcaneOrbSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(arcaneOrbSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const arcaneOrbSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r9e6'?165:arcaneOrbSizeBase(e);
const arcaneOrbGroundBase=drawGroundEffects;drawGroundEffects=()=>{arcaneOrbGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r9e6'):enemies)){let a=e.attack;if(e.species!=='r9e6'||e.hp<=0||a?.pattern!=='orbShiftingSanctuary'||!visibleAt(a.origin.x,a.origin.y)||e.elapsed>=3.3)continue;let phase=e.elapsed<1.6?0:1,angle=a.angle+phase*a.side*Math.PI*2/3,half=Math.PI*35/180,q=project(a.origin.x,a.origin.y),impact=e.elapsed>=3||(e.elapsed>=1.4&&e.elapsed<1.6);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,300,angle+half,angle+Math.PI*2-half);ctx.closePath();ctx.fillStyle=impact?'#afcaff66':'#b4c8ec22';ctx.strokeStyle='#a2c4ed';ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,300,angle-half,angle+half);ctx.closePath();ctx.fillStyle='#6ce3aa22';ctx.strokeStyle='#83f4ba';ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(Math.cos(angle)*110,Math.sin(angle)*110);ctx.lineTo(Math.cos(angle)*250,Math.sin(angle)*250);ctx.stroke();ctx.restore();}};

